-- Create "device_logs" table
CREATE TABLE "public"."device_logs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "level" character varying NOT NULL,
  "tag" character varying NOT NULL DEFAULT '',
  "message" character varying NOT NULL,
  "uptime_ms" bigint NOT NULL,
  "boot_count" bigint NOT NULL,
  "device_ts" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "device_id" uuid NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "device_logs_devices_logs" FOREIGN KEY ("device_id") REFERENCES "public"."devices" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "devicelog_created_at" to table: "device_logs"
CREATE INDEX "devicelog_created_at" ON "public"."device_logs" ("created_at");
-- Create index "devicelog_device_id_id" to table: "device_logs"
CREATE INDEX "devicelog_device_id_id" ON "public"."device_logs" ("device_id", "id");
